"""Install a selection-strategy section in the paired Transfermarkt report."""
import json
from pathlib import Path
OUT=Path(__file__).resolve().parents[1]/'results/transfermarkt_models'

def install(models,strategies,methods):
    section='''<!-- selection-strategies -->
<section id="betting-strategies"><h2>Compare betting-selection strategies</h2><p>All 15 existing selection rules, including legacy variance and its fixed filtered candidate. Baseline and Transfermarkt-enhanced models use the same matches.</p><div id="st-controls"></div><p class="note">Flat $1 follows the original selection even without positive model edge. Five levels ($1–$5), quarter Kelly and robust Kelly skip non-positive edges. Every sizing method has the same $1,000 initial bankroll, 2% per-match and 10% per-day caps. Synthetic double chance splits one total stake; these are not quoted double-chance odds. No mixture optimization or test-selected thresholds.</p><p id="st-status" role="status"></p><h3>All strategies · chosen model, league and sizing</h3><div id="st-summary" class="scroll"></div><h3>Chosen strategy · all leagues</h3><div id="st-leagues" class="scroll"></div><h3>Cumulative profit · chosen strategy and league</h3><svg id="st-chart" viewBox="0 0 1050 390" role="img" aria-label="Strategy cumulative profit comparison"></svg><div id="st-legend"></div></section>
<script>(function(){
const models=__MODELS__,strategies=__STRATEGIES__,methods=__METHODS__,selectors={},cache={};let rows=[],sequence=0;
for(const [field,values] of Object.entries({split:['Test','Train chronological OOF','Train in-sample'],model:models,league:['All','E0','SP1','D1','I1'],strategy:strategies,method:methods})){let label=document.createElement('label');label.textContent=field+' ';let s=document.createElement('select');s.setAttribute('aria-label','Strategy '+field);for(const v of values)s.add(new Option(v,v));if(field==='strategy')s.value='Legacy variance score';s.onchange=field==='model'||field==='split'?load:draw;selectors[field]=s;label.append(s);document.querySelector('#st-controls').append(label)}
const cash=x=>(x<0?'−':'')+'$'+Math.abs(x).toFixed(2),pct=x=>(x*100).toFixed(2)+'%';
function table(headers,rs){return '<table><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rs.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
async function load(){const seq=++sequence;const name='TM strategies '+selectors.model.value+' '+selectors.split.value;document.querySelector('#st-status').textContent='Loading strategy results…';try{if(!cache[name]){const response=await fetch('/bankroll-mixture.json?model='+encodeURIComponent(name));if(!response.ok)throw Error('Could not load strategy results');cache[name]=await response.json()}if(seq!==sequence)return;rows=cache[name].rows;document.querySelector('#st-status').textContent='Baseline → with Transfermarkt values. Profit is net dollars; drawdown is maximum daily peak-to-trough percentage.';draw()}catch(e){document.querySelector('#st-status').textContent=e.message}}
function pair(rs,key){const a=rs.find(r=>r.variant==='Baseline'),b=rs.find(r=>r.variant==='With values');return a&&b?[key,a.matches,cash(a.net),cash(b.net),cash(b.net-a.net),pct(a.max_drawdown),pct(b.max_drawdown),a.bets+' / '+b.bets]:null}
function draw(){const league=selectors.league.value,method=selectors.method.value,strategy=selectors.strategy.value;const eligible=rows.filter(r=>r.method===method);const heads=['Strategy / league','Matches','Baseline profit','With values profit','Profit change','Baseline max DD','With values max DD','Bets base / values'];document.querySelector('#st-summary').innerHTML=table(heads,strategies.map(s=>pair(eligible.filter(r=>r.league===league&&r.strategy===s),s)).filter(Boolean));document.querySelector('#st-leagues').innerHTML=table(heads,['All','E0','SP1','D1','I1'].map(l=>pair(eligible.filter(r=>r.league===l&&r.strategy===strategy),l)).filter(Boolean));const lines=eligible.filter(r=>r.league===league&&r.strategy===strategy);if(!lines.length)return;const dates=[...new Set(lines.flatMap(r=>r.points.map(p=>p.date)).filter(d=>d!=='Start'))].sort();const vals=lines.flatMap(r=>r.points.map(p=>p.net));let lo=Math.min(0,...vals),hi=Math.max(0,...vals);if(lo===hi)hi=lo+1;const y=v=>330-(v-lo)/(hi-lo)*290,x=d=>d==='Start'?90:90+(dates.indexOf(d)+1)/dates.length*900;let svg='';for(let i=0;i<5;i++){let v=lo+(hi-lo)*i/4;svg+=`<line x1="90" x2="990" y1="${y(v)}" y2="${y(v)}" stroke="#ddd"/><text x="0" y="${y(v)}">$${v.toFixed(0)}</text>`}const colors=['#9c6b29','#007a89'];lines.forEach((r,i)=>svg+=`<polyline fill="none" stroke="${colors[i]}" stroke-width="2.5" points="${r.points.map(p=>`${x(p.date)},${y(p.net)}`).join(' ')}"/>`);svg+=`<text x="90" y="365">${dates[0]}</text><text x="890" y="365">${dates.at(-1)}</text>`;document.querySelector('#st-chart').innerHTML=svg;document.querySelector('#st-legend').innerHTML=lines.map((r,i)=>`<span style="color:${colors[i]}">${r.variant}: ${cash(r.net)}</span>`).join(' | ')}load();
})();</script><!-- end-selection-strategies -->'''
    for marker,value in [('__MODELS__',models),('__STRATEGIES__',strategies),('__METHODS__',methods)]:section=section.replace(marker,json.dumps(value))
    path=OUT/'report.html';text=path.read_text(encoding='utf-8')
    if '<!-- selection-strategies -->' in text:
        a,b=text.split('<!-- selection-strategies -->',1);_,c=b.split('<!-- end-selection-strategies -->',1);text=a+c
    text=text.replace('<section><h2>Prediction quality</h2>',section+'<section><h2>Prediction quality</h2>',1)
    path.write_text(text,encoding='utf-8')
